ll{color:var(--cb-text-muted,#667085)}.sticky-action{position:fixed;z-index:5;left:0;right:0;bottom:0;display:flex;justify-content:center;align-items:center;gap:18px;padding:12px max(20px,env(safe-area-inset-right)) calc(12px + env(safe-area-inset-bottom));background:color-mix(in srgb,var(--cb-surface,#fff) 94%,transparent);border-top:1px solid #ddd}.sticky-action p{margin:0;color:var(--cb-text-muted,#667085)}@media(max-width:800px){.calculation-flow,.metrics{grid-template-columns:repeat(2,1fr)}.score-row{grid-template-columns:1fr 1fr}}@media(max-width:600px){.calculation-flow,.source-grid,.participant-grid,.score-row{grid-template-columns:1fr}.blocked,.result-state{align-items:flex-start;flex-direction:column}.sticky-action{align-items:stretch;flex-direction:column;gap:6px}.sticky-action .v-btn,.score-row .v-btn{width:100%;min-height:48px}.result-page{padding-bottom:145px}.application-list summary{align-items:flex-start}}
</style>
